-- ============================================
-- LUMA — Thème 11 : LONG 1/3 x4 — Un festival sur plusieurs jours avec des rebondissements
-- ============================================


update scenarios set content = '{"characters": {"friend": "ton ami(e)", "announcement": "annonce du festival"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "Day one! Three days of music ahead of us. Where should we start?", "text_fr": "Jour un ! Trois jours de musique devant nous. On commence où ?", "choices": [{"text": "Let''s check out the smaller stages first, discover new artists.", "text_fr": "Allons voir les petites scènes d''abord, pour découvrir de nouveaux artistes.", "next": "n2"}, {"text": "I say we head straight for the headliner stage to grab a good spot.", "text_fr": "Je dis qu''on va direct à la scène principale pour avoir une bonne place.", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(You discover an incredible unknown artist who instantly becomes a new favorite.)", "text_fr": "(Vous découvrez un artiste inconnu incroyable qui devient instantanément un nouveau favori.)", "choices": [{"text": "This is amazing, let''s remember this artist''s name for later.", "text_fr": "C''est génial, souvenons-nous du nom de cet artiste pour plus tard.", "next": "n3"}]}, "n2b": {"speaker": "friend", "text": "(You secure a great spot, but wait hours in growing heat.)", "text_fr": "(Vous sécurisez une super place, mais attendez des heures sous une chaleur grandissante.)", "choices": [{"text": "Worth it for this view, even with the wait.", "text_fr": "Ça vaut le coup pour cette vue, même avec l''attente.", "next": "n3"}]}, "n3": {"speaker": "narrator", "text": "(By evening, dark storm clouds begin gathering ominously overhead.)", "text_fr": "(Le soir venu, de sombres nuages d''orage commencent à s''amasser de façon menaçante au-dessus.)", "choices": [{"text": "(Check festival announcements for any weather updates.)", "text_fr": "(Vérifie les annonces du festival pour des mises à jour météo.)", "next": "n4"}]}, "n4": {"speaker": "announcement", "text": "Attention festival-goers: due to incoming severe weather, tonight''s headliner is postponed.", "text_fr": "Attention festivaliers : en raison de conditions météo sévères imminentes, le concert principal de ce soir est reporté.", "choices": [{"text": "That''s disappointing, but safety comes first, I suppose.", "text_fr": "C''est décevant, mais la sécurité avant tout, je suppose.", "next": "n5"}, {"text": "Let''s find shelter quickly before the storm hits.", "text_fr": "Trouvons un abri rapidement avant que l''orage frappe.", "next": "n5"}]}, "n5": {"speaker": "friend", "text": "(Huddled under a shelter tent, rain pouring outside) Well, this isn''t how I imagined day one ending.", "text_fr": "(Blottis sous une tente abri, la pluie tombant dehors) Bon, c''est pas comme ça que j''imaginais que le jour un se terminerait.", "choices": [{"text": "At least we''re making memories, even unexpected ones.", "text_fr": "Au moins on crée des souvenirs, même inattendus.", "next": "n6"}]}, "n6": {"speaker": "narrator", "text": "(The storm passes within an hour, leaving a muddy but hopeful festival ground.)", "text_fr": "(L''orage passe en une heure, laissant un terrain de festival boueux mais plein d''espoir.)", "choices": [{"text": "(Head back out to salvage what''s left of the evening.)", "text_fr": "(Retourne dehors pour sauver ce qui reste de la soirée.)", "next": "n7"}]}, "n7": {"speaker": "friend", "text": "(Day two) They rescheduled the headliner for this afternoon! Silver lining.", "text_fr": "(Jour deux) Ils ont reprogrammé le concert principal pour cet après-midi ! Un bon côté aux choses.", "choices": [{"text": "That''s great news! Let''s make sure we don''t miss it this time.", "text_fr": "C''est une super nouvelle ! Assurons-nous de pas le rater cette fois.", "next": "n8"}]}, "n8": {"speaker": "narrator", "text": "(The rescheduled set turns out to be even more special, with an intimate afternoon crowd.)", "text_fr": "(Le concert reprogrammé s''avère encore plus spécial, avec une foule intime d''après-midi.)", "choices": [{"text": "Honestly, this feels even better than a typical evening headliner set.", "text_fr": "Honnêtement, ça semble encore mieux qu''un concert principal typique du soir.", "next": "n9"}]}, "n9": {"speaker": "friend", "text": "Agreed! Sometimes unexpected changes lead to the best moments.", "text_fr": "D''accord ! Parfois les changements inattendus mènent aux meilleurs moments.", "choices": [{"text": "Speaking of unexpected — want to check out that small stage discovery from yesterday again?", "text_fr": "En parlant d''inattendu — tu veux revoir cette petite scène découverte d''hier ?", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(You return to find the same artist has drawn a much bigger, buzzing crowd today.)", "text_fr": "(Vous revenez pour trouver que le même artiste a attiré une foule bien plus grande et enthousiaste aujourd''hui.)", "choices": [{"text": "Word must have spread fast! I love seeing them get this recognition.", "text_fr": "Le bouche à oreille a dû se répandre vite ! J''adore les voir recevoir cette reconnaissance.", "next": "n11"}]}, "n11": {"speaker": "friend", "text": "(Day three, final day) Bittersweet, huh? Last day of this whole adventure.", "text_fr": "(Jour trois, dernier jour) Doux-amer, hein ? Dernier jour de toute cette aventure.", "choices": [{"text": "It really is. Let''s make today count more than ever.", "text_fr": "C''est vraiment le cas. Faisons que ce jour compte plus que jamais.", "next": "n12"}]}, "n12": {"speaker": "narrator", "text": "(As the final headliner takes the stage, the whole crowd feels the weight of the moment.)", "text_fr": "(Alors que le dernier concert principal commence, toute la foule ressent le poids du moment.)", "choices": [{"text": "(Soak in every second of this closing performance.)", "text_fr": "(Savoure chaque seconde de cette performance de clôture.)", "next": "n13"}]}, "n13": {"speaker": "friend", "text": "(As the final song ends, fireworks light up the sky above the crowd.)", "text_fr": "(Alors que la dernière chanson se termine, des feux d''artifice illuminent le ciel au-dessus de la foule.)", "choices": [{"text": "What a way to end three incredible, unpredictable days.", "text_fr": "Quelle façon de terminer trois jours incroyables et imprévisibles.", "next": "end_memorable"}]}, "end_memorable": {"speaker": "friend", "text": "Storms, surprises, new favorite artists — this festival gave us everything, honestly.", "text_fr": "Orages, surprises, nouveaux artistes préférés — ce festival nous a tout donné, honnêtement.", "end": true, "ending_label": "Trois jours de festival inoubliables malgré les imprévus 🎪⛈️🎆"}}}'::jsonb, is_playable = true
where title = 'Un festival sur plusieurs jours avec des rebondissements'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));
